// GENERATED by scripts/build.mjs, do not edit. Edit form-scanner/src or sankalpa-extension/src instead.
// Optional AI for writing bug reports. Providers work like the Prana app:
//   OpenRouter (free models only, your key) · Ollama (local, no key) · any OpenAI-compatible API (base URL + key).
// Shared by the web app (its server proxies the calls) and the extension (calls directly). Uses global fetch.

export const PROVIDERS = {
  openrouter: { label: 'OpenRouter (free models)', baseUrl: 'https://openrouter.ai/api/v1', needsKey: true },
  ollama: { label: 'Ollama (on this computer)', baseUrl: 'http://localhost:11434/v1', needsKey: false },
  custom: { label: 'Other OpenAI-compatible API', baseUrl: '', needsKey: false },
};

// Usual addresses of local model servers (same quick picks as Prana).
export const LOCAL_SERVERS = [
  { name: 'Ollama', baseUrl: 'http://localhost:11434/v1' },
  { name: 'LM Studio', baseUrl: 'http://localhost:1234/v1' },
  { name: 'text-generation-webui', baseUrl: 'http://localhost:5000/v1' },
  { name: 'vLLM', baseUrl: 'http://localhost:8000/v1' },
  { name: 'llama.cpp server', baseUrl: 'http://localhost:8080/v1' },
];

export const FORMATS = {
  markdown: 'Markdown (Jira Cloud, GitHub, GitLab, Linear, Azure DevOps)',
  jira: 'Jira wiki markup (Jira Server / Data Center)',
  text: 'Plain text (email, Slack, Teams)',
};

export const baseUrlOf = (cfg) => String(cfg.baseUrl || PROVIDERS[cfg.provider]?.baseUrl || '').trim().replace(/\/+$/, '');
export const isLocalUrl = (u) => { try { return /^(localhost|127\.0\.0\.1|\[::1\])$/i.test(new URL(u).hostname); } catch { return false; } };
const authHeaders = (cfg) => ({
  'Content-Type': 'application/json',
  ...(cfg.apiKey ? { Authorization: `Bearer ${cfg.apiKey}` } : {}),
  ...(cfg.provider === 'openrouter' ? { 'X-Title': 'Sankalpa' } : {}),
});

// fetch with messages that say what to do, instead of the browser's bare "Failed to fetch".
export class AiError extends Error { constructor(message, help) { super(message); this.help = help || null; } }
const pageOrigin = () => (typeof location !== 'undefined' && /^chrome-extension:/.test(location.origin) ? location.origin : null);
async function reach(cfg, url, init) {
  const base = baseUrlOf(cfg);
  const ollama = cfg.provider === 'ollama' || /:11434(\/|$)/.test(base);
  let res;
  try { res = await fetch(url, init); } catch {
    if (ollama) throw new AiError('Can\'t reach Ollama at localhost:11434. It is not running.', { text: 'Start it: open the Ollama app, or run this in Terminal, then click Load models again:', command: 'ollama serve' });
    if (isLocalUrl(base)) throw new AiError(`Can't reach ${base}. Is that model server running on this computer?`);
    throw new AiError(`Can't reach ${new URL(base).host}. Check your internet connection${pageOrigin() ? ', and allow access when Chrome asks' : ''}.`);
  }
  if (ollama && res.status === 403 && pageOrigin()) {
    throw new AiError('Ollama is running but blocks requests from browser extensions (its default safety setting).', {
      text: 'Allow Sankalpa in Ollama (its documented OLLAMA_ORIGINS setting). Stop Ollama (Ctrl+C in its Terminal window), then start it again with this command:',
      command: `OLLAMA_ORIGINS="${pageOrigin()}" ollama serve`,
      alt: `Using the Ollama app instead of Terminal? Run: launchctl setenv OLLAMA_ORIGINS "${pageOrigin()}" — then quit and reopen the Ollama app.`,
    });
  }
  return res;
}

async function asJson(res, what) {
  const text = await res.text();
  if (!res.ok) throw new Error(`${what} failed (HTTP ${res.status}): ${text.slice(0, 200)}`);
  try { return JSON.parse(text); } catch { throw new Error(`${what}: the provider did not return JSON`); }
}

// [{ id, name }] — OpenRouter lists only $0 models; Ollama lists installed models.
export async function listModels(cfg) {
  const base = baseUrlOf(cfg);
  if (!/^https?:\/\//i.test(base)) throw new Error('Enter a full http:// or https:// base URL.');
  if (cfg.provider === 'openrouter') {
    const data = await asJson(await reach(cfg, `${base}/models`), 'Loading OpenRouter models');
    return (data.data || [])
      .filter((m) => Number(m.pricing?.prompt) === 0 && Number(m.pricing?.completion) === 0)
      .map((m) => ({ id: m.id, name: m.name || m.id }))
      .sort((a, b) => a.name.localeCompare(b.name));
  }
  if (cfg.provider === 'ollama') {
    const root = base.replace(/\/v1$/, '');
    const data = await asJson(await reach(cfg, `${root}/api/tags`), 'Loading Ollama models');
    return (data.models || []).map((m) => ({ id: m.name, name: m.name }));
  }
  const data = await asJson(await reach(cfg, `${base}/models`, { headers: authHeaders(cfg) }), 'Loading models');
  return (data.data || data.models || []).map((m) => ({ id: m.id || m.name, name: m.name || m.id }));
}

export async function chat(cfg, messages, { maxTokens = 1400 } = {}) {
  const base = baseUrlOf(cfg);
  if (!cfg.model) throw new Error('Choose a model first (AI settings).');
  if (PROVIDERS[cfg.provider]?.needsKey && !cfg.apiKey) throw new Error('This provider needs an API key (AI settings).');
  const data = await asJson(await reach(cfg, `${base}/chat/completions`, {
    method: 'POST', headers: authHeaders(cfg),
    body: JSON.stringify({ model: cfg.model, messages, temperature: 0.2, max_tokens: maxTokens, stream: false }),
  }), 'The model request');
  const text = data.choices?.[0]?.message?.content;
  if (!text) throw new Error('The model returned an empty answer.');
  return text.replace(/^<think>[\s\S]*?<\/think>\s*/i, '').trim(); // some local models prepend their reasoning
}

// ---- What the model gets: the facts Sankalpa recorded, with secrets removed.
const SENSITIVE_KEY = /^(authorization|proxy-authorization|cookie|set-cookie|x-api-key|x-auth-token|x-csrf-token|x-xsrf-token|api[-_]?key|access[-_]?token|refresh[-_]?token|token|password|passwordrepeat|secret)$/i;
const SENSITIVE_VALUE = /^(Bearer|Basic)\s+\S+|eyJ[\w-]+\.[\w-]+\.[\w-]+/;
export function redact(value, key = '') {
  if (value == null) return value;
  if (typeof value === 'string') {
    if (SENSITIVE_KEY.test(key) && value) return '[removed]';
    return value.replace(new RegExp(SENSITIVE_VALUE.source, 'g'), '[removed]');
  }
  if (Array.isArray(value)) return value.map((v) => redact(v, key));
  if (typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, redact(v, k)]));
  return value;
}
// Redacts inside JSON text too (request/response bodies are stored as strings).
const redactText = (s) => {
  if (typeof s !== 'string') return redact(s);
  try { return JSON.stringify(redact(JSON.parse(s))); } catch { return redact(s); }
};
const clip = (s, n = 1500) => { s = String(s ?? ''); return s.length > n ? `${s.slice(0, n)}… [${s.length - n} more characters]` : s; };

// Severity and location come from the test itself, so the model doesn't have to guess them.
function judgement(row) {
  const c = row.case, d = row.detail || '';
  const server = c.part === 3 || ['Accepted', 'Rejected'].includes(c.expected);
  if (row.status === 'warn') return { where: server ? 'server' : 'browser (client-side)', severity: 'Low', reason: 'a warning: it works, but the message or behaviour could be clearer' };
  if (server && /saved the record anyway/.test(d)) return { where: 'server', severity: 'High', reason: 'the server says it rejected the data but stored it anyway' };
  if (server && /Server accepted it/.test(d)) return { where: 'server', severity: 'High', reason: 'the rule exists only in the browser; anyone sending the request directly can store invalid data' };
  if (server && /Server error/.test(d)) return { where: 'server', severity: 'High', reason: 'invalid input makes the server fail instead of returning a clear error' };
  if (server) return { where: 'server', severity: 'Medium', reason: 'server and browser rules differ, so users see errors the page did not warn about' };
  if (c.kind === 'labels') return { where: 'browser (client-side)', severity: 'Medium', reason: 'accessibility: screen-reader users cannot tell what the field is for' };
  return { where: 'browser (client-side)', severity: 'Medium', reason: 'usability problem in the page itself; no server behaviour is involved' };
}

export function bugFacts({ row, forms, settings = {}, run, suite, env = {} }) {
  const c = row.case;
  const ev = row.evidence || {};
  const form = forms.find((f) => f.key === c.form_key);
  const field = form?.fields.find((f) => f.key === c.field_key);
  const agreed = settings.agreedLimits?.[c.form_key]?.[c.field_key];
  const exchanges = (ev.responses || []).map((r) => ({
    request: `${r.method} ${r.url}`, requestHeaders: redact(r.headers || {}), requestBody: clip(redactText(r.body)),
    status: r.status, responseBody: clip(redactText(r.text)),
  }));
  const plainEvidence = Object.fromEntries(Object.entries(ev).filter(([k]) => !['responses', 'recheck', 'response'].includes(k)).map(([k, v]) => [k, redact(v, k)]));
  return {
    application: suite.origin,
    page: form?.url, reachedBy: form?.from ? `"${form.from.text}" on ${form.from.url}` : 'opened directly',
    form: form?.title, submitButton: form?.submitText,
    field: field ? {
      label: field.label || field.key, key: field.key, type: field.type, required: !!field.required,
      clientRule: field.probe ? { min: field.probe.clientMin, max: field.probe.clientMax, source: field.probe.source, counterShows: field.probe.counter?.of ?? null, errorAtLimit: field.probe.overMaxError || null } : null,
      agreedLimit: agreed?.max ?? null, html: clip(field.html, 600),
    } : null,
    testCase: { title: c.title, part: c.part, check: c.kind, input: c.input_kind, expected: c.expected, custom: !c.builtin },
    result: { status: row.status === 'warn' ? 'warning' : 'fail', detail: row.detail, changeSinceLastRun: row.change || null, ...(({ where, severity, reason }) => ({ whereTheProblemIs: where, suggestedSeverity: severity, severityReason: reason }))(judgement(row)) },
    evidence: plainEvidence,
    requests: exchanges,
    recheck: ev.recheck ? { purpose: 'Not a separate bug: Sankalpa re-sent the same unique values with a valid field value; an "already exists" reply proves the rejected request was saved.', status: ev.recheck.status, responseBody: clip(redactText(ev.recheck.text), 600) } : null,
    howToReproduce: exchanges.length
      ? 'The page itself does not let a user send this value (the browser checks it), so reproduce on the server: submit the form once with valid data, then re-send the request listed in "requests" with the field changed, using an API client (e.g. Postman or curl) or the browser DevTools Network panel ("Edit and resend"). Linked requests must be sent in order.'
      : 'Reproduce in the browser page itself, as described by the test case.',
    environment: { browser: env.browser || null, tool: `${env.generator || 'Sankalpa'}${env.version ? ` ${env.version}` : ''}`, run: run.id, runDate: `${run.started_at} UTC`, typing: settings.realTyping ? 'real keyboard' : 'emulated' },
  };
}

const FORMAT_RULES = {
  markdown: 'Write GitHub-flavoured Markdown: "## " headings, numbered lists for steps, fenced code blocks for requests, responses and HTML.',
  jira: 'Write Jira wiki markup (not Markdown): "h2. " headings, "# " numbered lists, "* " bullets, {code} or {code:json} blocks, *bold*.',
  text: 'Write plain text only: no Markdown symbols. Use UPPERCASE section names followed by a colon, numbered steps "1.", and indent code by 4 spaces.',
};

export function bugMessages(facts, format = 'markdown') {
  return [
    {
      role: 'system',
      content: [
        'You are a senior QA engineer writing one bug report for a developer ticket.',
        'Use ONLY the facts in the JSON you are given. Never invent URLs, values, versions or behaviour. If something is unknown, leave it out.',
        'Be specific and concise. Write for a developer who has not seen the test.',
        'Sections, in this order: Title (one line, starts with the form and field, says what is wrong) · Severity · Environment · Steps to reproduce · Expected result · Actual result · Why it matters (impact on users) · Suggested fix · Evidence (short excerpts of the request, response and field HTML that prove the problem).',
        'Severity: use result.suggestedSeverity and result.severityReason as given.',
        'Steps to reproduce must follow "howToReproduce". Report only the one problem in "result"; do not turn supporting evidence (such as "recheck") into extra bugs.',
        'result.whereTheProblemIs says where the bug is. If it is the browser (client-side), do not claim anything about the server accepting, saving or rejecting data; only describe server behaviour that appears in "requests".',
        'Do not include any secrets; values marked [removed] stay removed.',
        FORMAT_RULES[format] || FORMAT_RULES.markdown,
      ].join('\n'),
    },
    { role: 'user', content: `Facts recorded by Sankalpa (JSON):\n${JSON.stringify(facts, null, 2)}` },
  ];
}

export async function generateBugReport(cfg, facts, format) {
  return chat(cfg, bugMessages(facts, format));
}
